   170	        String id = ctx.pathParam("id");
   171	        try {
   172	            return Long.parseLong(id);
   173	        } catch (NumberFormatException notANumber) {
   174	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
   175	        }
   176	    }
   177	
   178	    private static LocalDate readDate(Context ctx) {
   179	        String date = requiredQueryParam(ctx, "date");
   180	        try {
   181	            return LocalDate.parse(date);
   182	        } catch (DateTimeParseException badDate) {
   183	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
   184	        }
